package com.bank.flink.mem;

import java.util.logging.Logger;

// Derives Flink memory regions from the process size and fractions, and
// validates them against RocksDB and parallelism requirements.
class MemoryModel {
    private static final Logger log = Logger.getLogger(MemoryModel.class.getName());

    final long metaspaceMb;
    final long overheadMb;
    final long flinkTotalMb;   // process - metaspace - overhead
    final long managedMb;
    final long networkMb;
    final long heapMb;         // the remainder (framework + task heap)

    MemoryModel(MemoryConfig c) {
        this.metaspaceMb = c.metaspaceMb;
        this.overheadMb = Math.round(c.processSizeMb * c.overheadFraction);
        this.flinkTotalMb = c.processSizeMb - metaspaceMb - overheadMb;
        this.managedMb = Math.round(flinkTotalMb * c.managedFraction);
        this.networkMb = Math.round(flinkTotalMb * c.networkFraction);
        this.heapMb = flinkTotalMb - managedMb - networkMb;
        log.info(() -> String.format(
                "regions: heap=%dMB managed=%dMB network=%dMB metaspace=%dMB overhead=%dMB",
                heapMb, managedMb, networkMb, metaspaceMb, overheadMb));
    }

    // RocksDB needs a minimum block cache working set (MB) to avoid disk thrash.
    boolean managedSufficientForRocksDb(long rocksWorkingSetMb) {
        boolean ok = managedMb >= rocksWorkingSetMb;
        if (!ok) log.severe(() -> "managed memory " + managedMb
                + "MB < RocksDB working set " + rocksWorkingSetMb + "MB -> disk thrash");
        else log.info(() -> "managed memory sufficient for RocksDB (" + managedMb + "MB)");
        return ok;
    }

    // Network buffers needed grow with parallelism (illustrative: ~8MB per slot).
    boolean networkSufficientForParallelism(int parallelism) {
        long required = 8L * parallelism;
        boolean ok = networkMb >= required;
        if (!ok) log.severe(() -> "network memory " + networkMb + "MB < required "
                + required + "MB for parallelism " + parallelism
                + " -> Insufficient number of network buffers");
        else log.info(() -> "network memory sufficient for parallelism " + parallelism);
        return ok;
    }
}
