package com.bank.flink.mem;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MemoryTuningDemo {
    private static final Logger log = Logger.getLogger(MemoryTuningDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        long rocksWorkingSet = 1200;  // MB needed by RocksDB block cache
        int peakParallelism = 64;     // scaled-up parallelism

        // Starved config: default fractions too low for this stateful, scaled job.
        log.info("=== STARVED CONFIG (defaults) ===");
        MemoryModel starved = new MemoryModel(
                new MemoryConfig(4096, 0.4, 0.1, 256, 0.1));
        starved.managedSufficientForRocksDb(rocksWorkingSet);   // fails
        starved.networkSufficientForParallelism(peakParallelism); // fails

        // Tuned config: raise managed + network fractions.
        log.info("=== TUNED CONFIG (raised fractions) ===");
        MemoryModel tuned = new MemoryModel(
                new MemoryConfig(4096, 0.5, 0.15, 256, 0.1));
        tuned.managedSufficientForRocksDb(rocksWorkingSet);     // passes
        tuned.networkSufficientForParallelism(peakParallelism);  // passes
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
